// ServicosSolicitados.js
import React, { useEffect, useState, useMemo } from 'react';
import { Plus, Pencil, Trash2 } from 'lucide-react';
import api from '../../api/axios';
import ServicoSolicitadoFormModal from './servicoSolicitadoFormModal';
import './servicos-solicitados.css';

export default function ServicosSolicitados() {
  const [solicitacoes, setSolicitacoes] = useState([]);
  const [empresas, setEmpresas] = useState([]);
  const [modalAberto, setModalAberto] = useState(false);
  const [solicitacaoSelecionada, setSolicitacaoSelecionada] = useState(null);

  // filtros
  const [filters, setFilters] = useState({
    empresa: '',       // busca por cod_folha OU razao_social
    responsavel: '',   // resp_dp
    grupo: '',         // grupo
  });

  useEffect(() => {
    carregarSolicitacoes();
    carregarEmpresas();
  }, []);

  const carregarSolicitacoes = async () => {
    const res = await api.get('/api/solicitacoes/');
    setSolicitacoes(res.data.results || res.data);
  };

  const carregarEmpresas = async () => {
    // carrega grande o suficiente para cobrir a lista
    const res = await api.get('/api/empresas/', { params: { page: 1, page_size: 2000 } });
    setEmpresas(res.data.results || res.data);
  };

  // Mapa rápido: cod_folha -> empresa
  const empresaByCodigo = useMemo(() => {
    const m = new Map();
    empresas.forEach(e => m.set(String(e.cod_folha), e));
    return m;
  }, [empresas]);

  // Opções únicas para selects
  const options = useMemo(() => {
    const uniq = (arr) => Array.from(new Set(arr.filter(Boolean))).sort((a, b) =>
      String(a).localeCompare(String(b), 'pt-BR', { sensitivity: 'base' })
    );
    return {
      responsavel: uniq(empresas.map(e => e.resp_dp)),
      grupo:       uniq(empresas.map(e => e.grupo)),
    };
  }, [empresas]);

  const normalizar = (v) =>
    String(v ?? '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim()
      .toUpperCase();

  // Aplica filtros
  const solicitacoesFiltradas = useMemo(() => {
    const termoEmp = normalizar(filters.empresa);
    const respAlvo = normalizar(filters.responsavel);
    const grupoAlvo = normalizar(filters.grupo);

    return solicitacoes.filter((s) => {
      const cod = String(s.empresa ?? '');
      const emp = empresaByCodigo.get(cod);

      // Se não encontrarmos a empresa, só passa se nenhum filtro que depende da empresa estiver ativo
      if (!emp) {
        if (termoEmp || respAlvo || grupoAlvo) return false;
        return true;
      }

      const codNorm = normalizar(emp.cod_folha);
      const razaoNorm = normalizar(emp.razao_social);
      const respNorm = normalizar(emp.resp_dp);
      const grupoNorm = normalizar(emp.grupo);

      const passaEmpresa =
        !termoEmp || codNorm.includes(termoEmp) || razaoNorm.includes(termoEmp);

      const passaResp = !respAlvo || respNorm === respAlvo;
      const passaGrupo = !grupoAlvo || grupoNorm === grupoAlvo;

      return passaEmpresa && passaResp && passaGrupo;
    });
  }, [solicitacoes, empresaByCodigo, filters]);

  const abrirModal = (solicitacao = null) => {
    setSolicitacaoSelecionada(solicitacao);
    setModalAberto(true);
  };

  const fecharModal = () => {
    setModalAberto(false);
    setSolicitacaoSelecionada(null);
    carregarSolicitacoes();
  };

  const excluir = async (id) => {
    if (window.confirm('Confirma a exclusão?')) {
      await api.delete(`/api/solicitacoes/${id}/`);
      carregarSolicitacoes();
    }
  };

  const renderEmpresa = (valorEmpresa) => {
    const cod = String(valorEmpresa ?? '');
    const emp = empresaByCodigo.get(cod);
    return emp ? `${emp.cod_folha} — ${emp.razao_social}` : cod;
  };

  const handleFilterChange = (campo) => (e) => {
    const val = e.target ? e.target.value : e; // para select/native input
    setFilters((prev) => ({ ...prev, [campo]: val }));
  };

  const limparFiltros = () => setFilters({ empresa: '', responsavel: '', grupo: '' });

  return (
    <div className="servicos-container">
      <div className="servicos-header">
        <h2>Serviços Solicitados</h2>
        <button onClick={() => abrirModal()} title="Novo Serviço">
          <Plus size={18} /> Novo
        </button>
      </div>

      {/* Filtros */}
      <div className="servicos-filtros" style={{ display: 'flex', gap: 8, alignItems: 'flex-end', margin: '8px 0' }}>
        <div className="campo" style={{ minWidth: 280 }}>
          <label>Empresa (código ou razão)</label>
          <input
            type="text"
            value={filters.empresa}
            onChange={handleFilterChange('empresa')}
            placeholder="Ex.: 0123 ou ACME LTDA"
          />
        </div>

        <div className="campo" style={{ minWidth: 200 }}>
          <label>Responsável</label>
          <select value={filters.responsavel} onChange={handleFilterChange('responsavel')}>
            <option value="">Todos</option>
            {options.responsavel.map((r) => (
              <option key={r} value={r}>{r}</option>
            ))}
          </select>
        </div>

        <div className="campo" style={{ minWidth: 180 }}>
          <label>Grupo</label>
          <select value={filters.grupo} onChange={handleFilterChange('grupo')}>
            <option value="">Todos</option>
            {options.grupo.map((g) => (
              <option key={g} value={g}>{g}</option>
            ))}
          </select>
        </div>

        <div>
          <button type="button" onClick={limparFiltros} title="Limpar filtros">
            Limpar
          </button>
        </div>
      </div>

      <table>
        <thead>
          <tr>
            <th>Empresa</th>
            <th>Serviço</th>
            <th>Competência</th>
            <th>Solicitação</th>
            <th>Vencimento</th>
            <th>Conclusão</th>
            <th>Ações</th>
          </tr>
        </thead>
        <tbody>
          {solicitacoesFiltradas.map((s) => (
            <tr key={s.id}>
              <td>{renderEmpresa(s.empresa)}</td>
              <td>{s.servico_nome}</td>
              <td>{s.competencia}</td>
              <td>{s.data_solicitacao}</td>
              <td>{s.data_vencimento || '-'}</td>
              <td>{s.data_conclusao || '-'}</td>
              <td className="acoes">
                <button onClick={() => abrirModal(s)} title="Editar">
                  <Pencil size={16} />
                </button>
                <button onClick={() => excluir(s.id)} title="Excluir">
                  <Trash2 size={16} />
                </button>
              </td>
            </tr>
          ))}

          {solicitacoesFiltradas.length === 0 && (
            <tr>
              <td colSpan={7} style={{ textAlign: 'center', opacity: 0.7, padding: '8px 0' }}>
                Nenhum registro encontrado com os filtros atuais.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {modalAberto && (
        <ServicoSolicitadoFormModal
          dados={solicitacaoSelecionada}
          fechar={fecharModal}
        />
      )}
    </div>
  );
}
